import {spawn} from 'node:child_process';
import {fileURLToPath} from 'node:url';

const MAX_INPUT = 64 * 1024;
const MAX_XML = 1024 * 1024;
const PARSE_MS = 200;
const MAX_RSS_KB = 96 * 1024;
const MAX_QUEUED = 2;
const worker = fileURLToPath(new URL('./parser-worker.mjs', import.meta.url));
let active = false;
const queue = [];

function runParser(buffer) {
  return new Promise((resolve, reject) => {
    // Keep the parser's inherited environment deliberately small. The vendor
    // library runs only in this child, never in the HTTP server process.
    const child = spawn(process.execPath, [worker], {
      stdio: ['pipe', 'pipe', 'ignore'],
      env: {PATH: process.env.PATH || '/usr/bin:/bin'},
    });
    let stdout = '';
    let settled = false;
    let parsing = false;
    let timer;
    const finish = (error, value) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      clearInterval(memoryPoll);
      if (error) reject(error); else resolve(value);
    };
    const kill = (reason) => { child.kill('SIGKILL'); finish(new Error(reason)); };
    child.stdout.setEncoding('utf8');
    child.stdout.on('data', chunk => {
      stdout += chunk;
      if (Buffer.byteLength(stdout) > MAX_XML + 128) kill('oversized result');
    });
    child.on('error', error => finish(error));
    child.on('close', code => {
      if (settled) return;
      if (code !== 0) return finish(new Error('parser failed'));
      try {
        const result = JSON.parse(stdout);
        if (typeof result.xml !== 'string' || Buffer.byteLength(result.xml) > MAX_XML) throw new Error('oversized XML');
        finish(null, result.xml);
      } catch (error) { finish(error); }
    });
    const memoryPoll = setInterval(async () => {
      if (settled || !child.pid) return;
      // ps is available on supported deployment platforms and lets us enforce
      // an RSS ceiling even where the runtime has no rlimit API.
      try {
        const {execFile} = await import('node:child_process');
        execFile('ps', ['-o', 'rss=', '-p', String(child.pid)], (error, out) => {
          const rss = Number(String(out).trim());
          if (!error && rss > MAX_RSS_KB) kill('parser memory limit');
        });
      } catch {}
    }, 10);
    child.stdin.on('error', () => {});
    child.stdin.end(buffer);
    // Time the actual vendor extraction; process startup is outside the budget.
    child.once('spawn', () => {
      // Worker emits a start marker before invoking the library.
    });
    timer = setTimeout(() => kill('parser timeout'), PARSE_MS);
  });
}

async function processJob(buffer) {
  try {
    const xml = await runParser(buffer);
    const title = /<title>(.*?)<\/title>/s.exec(xml)?.[1];
    if (!title) throw new Error('no title');
    return {status: 200, body: {kind: 'proposal', title}};
  } catch {
    return {status: 422, body: {kind: 'unreadable', kept: true}};
  }
}

function drain() {
  if (active || queue.length === 0) return;
  active = true;
  const {buffer, resolve} = queue.shift();
  processJob(buffer).then(resolve).finally(() => { active = false; drain(); });
}

export function upload(buffer) {
  if (buffer.length > MAX_INPUT) return Promise.resolve({status: 422, body: {kind: 'unreadable', kept: true}});
  if (active && queue.length >= MAX_QUEUED) return Promise.resolve({status: 503, body: {kind: 'busy', kept: true}});
  return new Promise(resolve => {
    queue.push({buffer, resolve});
    drain();
  });
}

